bh=re.sub(r'<title>.*?</title>',f'<title>{btitle} | HomeCostEngine</title>',header).replace('https://homecostengine.com/ebooks/'+slug,'https://homecostengine.com/blog/'+blog)
bh=re.sub(r'<meta property="og:type" content="product">','<meta property="og:type" content="article">',bh);bh=bh.replace('property="og:title" content="'+title+'"','property="og:title" content="'+btitle+'"')
